<?php
function flow_state($id){return geo_raw('SELECT * FROM issue_flow WHERE issue_id=?',[$id])->fetch()?:['issue_id'=>$id,'location_state'=>'pending','location_hash'=>null,'location_note'=>null,'accepted_by'=>null,'accepted_at'=>null,'block_reason'=>null,'block_kind'=>null,'next_review'=>null,'reopen_state'=>'none','reopen_reason'=>null,'reopen_photo'=>null,'version'=>0];}
function flow_location_hash($i){$parts=[];foreach(['province_id','district_id','town_id','latitude','longitude','address'] as $key)$parts[$key]=(string)($i[$key]??'');return hash('sha256',json_encode($parts));}
function flow_location_ready($i){$f=flow_state($i['id']);return !followup_location_result($i)['outside']&&$f['location_state']==='reviewed'&&hash_equals((string)$f['location_hash'],flow_location_hash($i));}
function flow_team_eligible($team,$category){return (bool)geo_raw('SELECT team_id FROM team_categories WHERE team_id=? AND category_id=?',[$team,$category])->fetchColumn();}
function flow_guard($action){
 if(!user())return;
 if(($action==='admin_review_issue'&&($_POST['decision']??'')==='Verified')||$action==='assign_officer'||($action==='update_issue'&&($_POST['status']??'')==='Verified')){$i=geo_require_issue((int)($_POST['issue_id']??0));if(!flow_location_ready($i))throw new RuntimeException('Check the map pin and Province / District / Town using Workflow controls before verification or assignment.');}
 if($action==='team_assign'){$i=geo_require_issue((int)($_POST['issue_id']??0));if(!flow_team_eligible((int)($_POST['maintenance_id']??0),$i['category_id']))throw new RuntimeException('Choose a town team configured for this issue category.');$f=flow_state($i['id']);if(!geo_system()&&(int)$f['accepted_by']!==(int)user()['id'])throw new RuntimeException('Accept responsibility before dispatching a team.');}
 if(user()['role']==='officer'&&in_array($action,['team_review','flow_return_team','flow_resume'],true)){$i=geo_require_issue((int)($_POST['issue_id']??0));$f=flow_state($i['id']);if((int)$f['accepted_by']!==(int)user()['id'])throw new RuntimeException('Accept District Officer responsibility before making this work decision.');}
 if($action==='geo_relocate'){geo_system_required();$i=geo_require_issue((int)($_POST['issue_id']??0));if(($i['officer_id']||$i['maintenance_id'])&&!in_array($i['status'],['Resolved','Rejected','Duplicate'],true)&&($_POST['confirm_transfer']??'')!=='1')throw new RuntimeException('Confirm the active routing transfer: assignments are cleared and work returns to review; evidence remains.');}
 if($action==='update_issue'){$i=geo_require_issue((int)($_POST['issue_id']??0));$next=$_POST['status']??'';if(!hash_equals(assignment_revision($i),(string)($_POST['previous_revision']??'')))throw new RuntimeException('This report changed. Refresh before updating it.');if($i['status']==='Awaiting Approval'&&$next!==$i['status']&&user()['role']!=='admin')throw new RuntimeException('Only the Province Admin reviews final approval.');if($next==='Resolved'&&$i['status']!=='Resolved'&&($i['status']!=='Awaiting Approval'||$i['maintenance_stage']!=='Approved'||!$i['maintenance_photo']))throw new RuntimeException('District Officer approval of team evidence is required before final resolution.');}
}
function flow_action($action,$delegated=false){
 if(!in_array($action,['flow_team_categories','flow_location','flow_accept','flow_block','flow_resume','flow_return_team','flow_internal_note','flow_reopen_review','reopen'],true))return;
 require_login();$roles=['flow_team_categories'=>['admin','officer'],'flow_location'=>['admin'],'flow_accept'=>['officer'],'flow_block'=>['maintenance'],'flow_resume'=>['maintenance','officer'],'flow_return_team'=>['officer'],'flow_internal_note'=>['admin','officer','maintenance'],'flow_reopen_review'=>['admin'],'reopen'=>['citizen','admin']];if(!$delegated)require_role($roles[$action]);$photo=null;
 if($action==='flow_team_categories'){
  if($delegated&&!management_allows('town'))throw new RuntimeException('Only the Maintenance Team Admin can manage categories nationwide.');
  if(!$delegated)require_role(['admin','officer']);
  $team=(int)($_POST['team_id']??0);$lookup=$delegated?'geo_raw':'q';$u=$lookup("SELECT * FROM users WHERE id=? AND role='maintenance'",[$team])->fetch();if(!$u)throw new RuntimeException('Choose a team in your permitted area.');$ids=array_values(array_unique(array_map('intval',(array)($_POST['category_ids']??[]))));if(!$ids)throw new RuntimeException('Select at least one service category.');foreach($ids as $id)if(!geo_raw('SELECT c.id FROM categories c WHERE c.id=? AND (c.active=1 OR EXISTS(SELECT 1 FROM team_categories tc WHERE tc.team_id=? AND tc.category_id=c.id))',[$id,$team])->fetchColumn())throw new RuntimeException('Choose valid active categories.');
  db()->beginTransaction();if(geo_raw("SELECT id FROM issues WHERE maintenance_id=? AND status NOT IN ('Resolved','Rejected','Duplicate') AND category_id NOT IN (".implode(',',$ids).') LIMIT 1',[$team])->fetch())throw new RuntimeException('Keep categories needed by current open work.');geo_raw('DELETE FROM team_categories WHERE team_id=?',[$team]);foreach($ids as $id)geo_raw('INSERT INTO team_categories(team_id,category_id) VALUES(?,?)',[$team,$id]);audit('team.categories','Team #'.$team.' categories '.implode(',',$ids));db()->commit();flash('Team service categories saved.');go($delegated?'index.php?page=management&team='.$team:'index.php?page=flow&tab=teams');
 }
 try{
  db()->beginTransaction();$id=(int)($_POST['issue_id']??0);$i=q('SELECT * FROM issues WHERE id=? FOR UPDATE',[$id])->fetch();if(!$i)throw new RuntimeException('Report not found.');if(user()['role']==='citizen'&&(int)$i['user_id']!==(int)user()['id'])throw new RuntimeException('Only the reporter may request reopening.');geo_raw('INSERT IGNORE INTO issue_flow(issue_id) VALUES(?)',[$id]);$f=flow_state($id);if(!isset($_POST['flow_version'])||(int)$_POST['flow_version']!==(int)$f['version'])throw new RuntimeException('Workflow details changed. Refresh before saving.');if($i['duplicate_of'])throw new RuntimeException('Use the original report.');$note=field('note',5,2000);$role=user()['role'];$active=in_array($i['status'],['Assigned','In Progress'],true);
  if($action==='flow_location'){
   require_role('admin');if(!hash_equals(flow_location_hash($i),(string)($_POST['location_snapshot']??'')))throw new RuntimeException('The location changed. Review the current pin and address.');$state=(string)($_POST['location_state']??'');if($state==='reviewed')followup_check_location($i);if(!in_array($state,['reviewed','flagged'],true)||in_array($i['status'],['Resolved','Rejected','Duplicate'],true))throw new RuntimeException('Choose a valid review on an open report.');geo_raw('UPDATE issue_flow SET location_state=?,location_hash=?,location_note=?,location_reviewer=? WHERE issue_id=?',[$state,flow_location_hash($i),$note,user()['id'],$id]);event_add($id,'location_review',$state==='reviewed'?'Province Admin checked the location and map pin.':'Location needs correction before assignment.');
  }elseif($action==='flow_accept'){
   require_role('officer');if(!$active||(int)$i['officer_id']!==(int)user()['id']||(int)$f['accepted_by']===(int)user()['id'])throw new RuntimeException('Accept only your new district assignment.');geo_raw('UPDATE issue_flow SET accepted_by=?,accepted_at=NOW() WHERE issue_id=?',[user()['id'],$id]);event_add($id,'accepted','District Officer accepted responsibility. '.$note);geo_notify_admin($i,'District Officer accepted report #'.$id);
  }elseif($action==='flow_block'){
   require_role('maintenance');if(!$active||$i['maintenance_stage']!=='In Progress'||(int)$i['maintenance_id']!==(int)user()['id'])throw new RuntimeException('Only your work in progress can be blocked.');$kind=(string)($_POST['block_kind']??'');if(!in_array($kind,['Materials','Access','External agency','Other'],true))throw new RuntimeException('Select a blocking reason.');$review=valid_date((string)($_POST['next_review']??''),'next review');if(!$review||$review<date('Y-m-d'))throw new RuntimeException('Choose today or a future review date.');geo_raw('UPDATE issue_flow SET block_kind=?,block_reason=?,next_review=? WHERE issue_id=?',[$kind,$note,$review,$id]);q("UPDATE issues SET maintenance_stage='Blocked',maintenance_version=maintenance_version+1 WHERE id=?",[$id]);event_add($id,'blocked','Work blocked: '.$kind.'. Next review: '.$review.'. '.$note);notify_issue($i,'Work blocked on report #'.$id.'. District Officer follow-up required.');geo_notify_admin($i,'Work blocked on report #'.$id);
  }elseif($action==='flow_resume'){
   require_role(['maintenance','officer']);if(!$active||$i['maintenance_stage']!=='Blocked'||($role==='maintenance'&&(int)$i['maintenance_id']!==(int)user()['id'])||($role==='officer'&&(int)$i['officer_id']!==(int)user()['id']))throw new RuntimeException('Resume only your blocked assignment.');geo_raw('UPDATE issue_flow SET block_kind=NULL,block_reason=NULL,next_review=NULL WHERE issue_id=?',[$id]);q("UPDATE issues SET maintenance_stage='In Progress',maintenance_version=maintenance_version+1 WHERE id=?",[$id]);event_add($id,'resumed','Work resumed. '.$note);notify_issue($i,'Work resumed on report #'.$id);
  }elseif($action==='flow_return_team'){
   require_role('officer');if(!$active||$i['maintenance_stage']!=='Officer Return'||(int)$i['officer_id']!==(int)user()['id']||!$i['maintenance_id'])throw new RuntimeException('No Province Admin return is waiting for your team decision.');maintenance_return($i,$note);event_add($id,'maintenance','Officer returned work to the maintenance team. '.$note);notify_issue($i,'District Officer returned report #'.$id.' to the team.');
  }elseif($action==='flow_internal_note'){
   require_role(['admin','officer','maintenance']);if($role==='maintenance'&&(int)$i['maintenance_id']!==(int)user()['id'])throw new RuntimeException('This is not your team assignment.');geo_raw('INSERT INTO issue_internal_notes(issue_id,user_id,message) VALUES(?,?,?)',[$id,user()['id'],$note]);
  }elseif($action==='reopen'){
   require_role(['citizen','admin']);if($i['status']!=='Resolved'||$f['reopen_state']==='pending')throw new RuntimeException('A resolved report without a pending request is required.');$photo=photo_upload('reopen_photo',true);q("INSERT INTO issue_progress_photos(issue_id,user_id,filename,note,phase) VALUES(?,?,?,?,'progress')",[$id,user()['id'],$photo,'Reopen evidence. '.$note]);geo_raw("UPDATE issue_flow SET reopen_state='pending',reopen_reason=?,reopen_photo=?,reopen_requested_at=NOW() WHERE issue_id=?",[$note,$photo,$id]);event_add($id,'reopen_request','Reopen requested with new evidence. '.$note);geo_notify_admin($i,'Reopen request needs review: report #'.$id);
  }elseif($action==='flow_reopen_review'){
   require_role('admin');if($i['status']!=='Resolved'||$f['reopen_state']!=='pending')throw new RuntimeException('No pending reopen request.');$decision=(string)($_POST['decision']??'');if(!in_array($decision,['accepted','rejected'],true))throw new RuntimeException('Choose a reopen decision.');if($decision==='accepted'){archive_resolution_evidence($i);maintenance_release($i,'Reopening approved; report returns to Province Admin review.');q("UPDATE issues SET status='Submitted',officer_id=NULL,resolution_photo=NULL,resolved_at=NULL,due_date=NULL WHERE id=?",[$id]);geo_raw("UPDATE issue_flow SET location_state='pending',location_hash=NULL,location_note=NULL,location_reviewer=NULL,accepted_by=NULL,accepted_at=NULL,block_kind=NULL,block_reason=NULL,next_review=NULL WHERE issue_id=?",[$id]);$feedback=q('SELECT rating,comment FROM issue_feedback WHERE issue_id=?',[$id])->fetch();if($feedback){event_add($id,'previous_feedback','Previous feedback: '.$feedback['rating'].'. '.$feedback['comment']);q('DELETE FROM issue_feedback WHERE issue_id=?',[$id]);}}geo_raw('UPDATE issue_flow SET reopen_state=? WHERE issue_id=?',[$decision,$id]);event_add($id,'reopen_review','Province Admin '.$decision.' reopening. '.$note);notify_issue($i,'Reopen request '.$decision.' for report #'.$id);
  }
  geo_raw('UPDATE issue_flow SET version=version+1 WHERE issue_id=?',[$id]);audit('issue.'.$action,'Issue #'.$id);db()->commit();
 }catch(Throwable $e){if(db()->inTransaction())db()->rollBack();remove_photo($photo);throw $e;}
 flash($action==='reopen'?'Reopen request submitted for Province Admin review.':'Workflow updated.');go('index.php?page='.($role==='maintenance'?'team_work':'issue').'&id='.$id.'#workflow');
}

function flow_validate_backup($data){
 $users=array_column($data['users'],null,'id');$issues=array_column($data['issues'],null,'id');$cats=array_column($data['categories'],null,'id');$seen=[];
 foreach($data['team_categories'] as $row){$key=$row['team_id'].':'.$row['category_id'];if(isset($seen[$key])||!isset($users[$row['team_id']])||$users[$row['team_id']]['role']!=='maintenance'||!isset($cats[$row['category_id']]))throw new RuntimeException('Invalid team categories in backup.');$seen[$key]=true;}
 $seen=[];foreach($data['issue_flow'] as $row){if(isset($seen[$row['issue_id']])||!isset($issues[$row['issue_id']])||!in_array($row['location_state'],['pending','reviewed','flagged'],true)||!in_array($row['reopen_state'],['none','pending','accepted','rejected'],true))throw new RuntimeException('Invalid workflow records in backup.');$seen[$row['issue_id']]=true;if($row['reopen_photo']!==null){$found=false;foreach($data['issue_progress_photos'] as $p)if((int)$p['issue_id']===(int)$row['issue_id']&&$p['filename']===$row['reopen_photo'])$found=true;if(!$found)throw new RuntimeException('Reopen evidence is missing from backup history.');}}
 foreach($data['issue_internal_notes'] as $row)if(!isset($issues[$row['issue_id']],$users[$row['user_id']]))throw new RuntimeException('Invalid private note reference in backup.');
}

function flow_normalize_backup(&$data,&$manifest,$tables){
 $new=['category_service_targets','temporary_cover','geo_service_boundaries'];$flow=['team_categories','issue_flow','issue_internal_notes'];
 $preFollowup=array_values(array_diff($tables,$new));$preFlow=array_values(array_diff($tables,array_merge($flow,$new)));
 if(array_keys($data)===$preFollowup||array_keys($data)===$preFlow){foreach($tables as $table)if(!array_key_exists($table,$data)){$data[$table]=[];$manifest['columns'][$table]=ops_columns($table);$manifest['counts'][$table]=0;}}
}
